window.docContents[230].resolve({"/Elementary-Functions/___4___3-Graphics/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___3-Graphics--___4___3-Graphics--___4___3_LPAR_i_RPAR_-Real-Arguments":{"contents":"Source: DLMF §4.3(i).\n\n\\[\\ln x\\quad\\text{and}\\quad {\\mathrm e}^{x}.\\] The curves are mirror images in the line y=x: their parallel tangents at\n(1,0) and (0,1) make the inverse relationship visible.  On the real line,\nlog and exp are inverse everywhere in the direction log (exp x) = x, and\nthe reverse direction holds on the positive half-line.\n\n","context":"LMLF · DLMF with Lean\u0009Elementary Functions\u0009§4.3 Graphics\u0009§4.3 Graphics","header":"§4.3(i) Real Arguments","id":"/Elementary-Functions/___4___3-Graphics/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___3-Graphics--___4___3-Graphics--___4___3_LPAR_i_RPAR_-Real-Arguments"}});